#!/usr/bin/env python3
"""Run the LihFolk checker after Codex applies a patch to Luau source."""

# Generated by LihFolk V2 Codex integration.
# Adapted from LihFolk Vault V2 by LihFolk; CC BY 4.0: https://creativecommons.org/licenses/by/4.0/.

from __future__ import annotations

import json
import os
import re
import subprocess
import sys
from pathlib import Path
from typing import Any


PATCH_FILE = re.compile(r"^\*\*\* (?:Update|Add|Delete) File:\s*(.+?)\s*$")
MOVE_FILE = re.compile(r"^\*\*\* Move to:\s*(.+?)\s*$")
UNIFIED_FILE = re.compile(r"^\+\+\+ (?:b/)?(.+?)\s*$")
MAX_FINDINGS = 12
GENERATED_MARKER = "Generated by LihFolk V2 Codex integration."


def project_root_for(cwd: Path) -> Path:
    for candidate in (cwd, *cwd.parents):
        if (candidate / ".codex" / "hooks.json").is_file() or (candidate / ".git").exists():
            return candidate
    return cwd


def configured_vault_root(project_root: Path) -> Path | None:
    env_value = os.environ.get("LIHFOLK_VAULT_ROOT")
    if env_value:
        candidate = Path(env_value).expanduser()
        if candidate.is_dir():
            return candidate.resolve()
    config = project_root / ".lihfolk-codex.json"
    if config.is_file():
        try:
            data = json.loads(config.read_text(encoding="utf-8"))
            value = data.get("vault_root") if isinstance(data, dict) else None
            if isinstance(value, str) and value.strip():
                candidate = Path(value).expanduser()
                if not candidate.is_absolute():
                    candidate = config.parent / candidate
                if candidate.is_dir():
                    return candidate.resolve()
        except (OSError, json.JSONDecodeError):
            return None
    if (project_root / "LihFolk Vault V2" / "_tools" / "vault.py").is_file():
        return project_root
    return None


def file_paths_from_event(event: dict[str, Any], cwd: Path, project_root: Path) -> list[Path]:
    tool_name = event.get("tool_name")
    if tool_name not in {"apply_patch", "Write", "Edit"}:
        return []
    tool_input = event.get("tool_input")
    candidates: list[str] = []
    if isinstance(tool_input, dict):
        for key in ("file_path", "path"):
            value = tool_input.get(key)
            if isinstance(value, str):
                candidates.append(value)
        edits = tool_input.get("edits")
        if isinstance(edits, list):
            for edit in edits:
                if isinstance(edit, dict):
                    value = edit.get("file_path") or edit.get("path")
                    if isinstance(value, str):
                        candidates.append(value)
        patch = tool_input.get("command") or tool_input.get("patch")
    else:
        patch = tool_input if isinstance(tool_input, str) else None

    if isinstance(patch, str):
        for line in patch.splitlines():
            for pattern in (PATCH_FILE, MOVE_FILE, UNIFIED_FILE):
                match = pattern.match(line)
                if match:
                    value = match.group(1).strip()
                    if value != "/dev/null":
                        candidates.append(value)
                    break

    resolved: dict[str, Path] = {}
    project_root = project_root.resolve()
    for value in candidates:
        path = Path(value.strip('"'))
        if not path.is_absolute():
            path = cwd / path
        path = path.resolve()
        try:
            path.relative_to(project_root)
        except ValueError:
            continue
        if path.suffix.lower() not in {".lua", ".luau"} or not path.is_file():
            continue
        if any(part in {".git", "node_modules", "Packages", "DevPackages", "ServerPackages", "_Index"} for part in path.parts):
            continue
        resolved[str(path)] = path
    return list(resolved.values())[:50]


def hook_message(event: dict[str, Any]) -> dict[str, Any] | None:
    cwd_value = event.get("cwd")
    cwd = Path(cwd_value).expanduser() if isinstance(cwd_value, str) and cwd_value else Path.cwd()
    if not cwd.is_dir():
        return None
    cwd = cwd.resolve()
    project_root = project_root_for(cwd).resolve()
    paths = file_paths_from_event(event, cwd, project_root)
    if not paths:
        return None

    vault_root = configured_vault_root(project_root)
    if vault_root is None:
        return {
            "systemMessage": "LihFolk Codex hook could not find the configured vault root; run the project installer or set LIHFOLK_VAULT_ROOT."
        }
    checker = vault_root / "scripts" / "lihfolk_check.py"
    if not checker.is_file():
        return {"systemMessage": f"LihFolk Codex hook checker is missing: {checker}"}

    try:
        result = subprocess.run(
            [sys.executable, str(checker), "--scan", *(str(path) for path in paths)],
            cwd=cwd,
            text=True,
            encoding="utf-8",
            errors="replace",
            capture_output=True,
            timeout=25,
            check=False,
        )
    except (OSError, subprocess.TimeoutExpired) as exc:
        return {"systemMessage": f"LihFolk Codex hook could not run the Luau checker: {exc}"}

    output = result.stdout.strip()
    if result.returncode not in (0, 1):
        detail = result.stderr.strip() or output or f"checker exited with {result.returncode}"
        return {"systemMessage": f"LihFolk Codex hook checker failed; the edit was not blocked. {detail[:1200]}"}
    if not output or "issue(s)" not in output and "error(s)" not in output and "warning(s)" not in output and "info." not in output:
        return None

    lines = output.splitlines()
    summary = next((line for line in reversed(lines) if line.startswith("LihFolk check:")), "")
    findings = [line for line in lines if line and not line.startswith("LihFolk check:")]
    shown = findings[:MAX_FINDINGS]
    if len(findings) > MAX_FINDINGS:
        shown.append(f"... {len(findings) - MAX_FINDINGS} more finding(s); run the project audit for the full list.")
    feedback = "LihFolk Roblox/Luau checker findings in the changed file(s):\n" + "\n".join(shown)
    if summary:
        feedback += "\n" + summary

    hook_specific = {
        "hookEventName": "PostToolUse",
        "additionalContext": feedback,
    }
    response: dict[str, Any] = {"hookSpecificOutput": hook_specific}
    if result.returncode == 1:
        response["decision"] = "block"
        response["reason"] = feedback
    return response


def main() -> int:
    try:
        event = json.load(sys.stdin)
    except (json.JSONDecodeError, UnicodeDecodeError):
        return 0
    if not isinstance(event, dict) or event.get("hook_event_name") != "PostToolUse":
        return 0
    response = hook_message(event)
    if response is not None:
        json.dump(response, sys.stdout, ensure_ascii=False, separators=(",", ":"))
        sys.stdout.write("\n")
    return 0


if __name__ == "__main__":
    raise SystemExit(main())
